DEBUG=false
SANDBOX_NAME=""
CONNECT_NAME=""
DELETE_NAME=""
LIST_MODE=false
FETCH_SERVICE_MODE=false
NO_CLONE=false
NO_CONNECT=false
DOWNLOAD_MODE=false
UPLOAD_MODE=false
