ADD_REPO_MODE=false
CREATE_MODE=false
ENSURE_MODE=false
REFRESH_MODE=false
RECREATE_MODE=false
GATEWAY=""
POLICY_FILE=""
SANDBOX_PROFILE=""
PROFILE_FROM_CLI=false
SOURCE_DIR=""
REPOS=()
